public class AuditLog implements java.io.Serializable, java.lang.Cloneable {
    private static final long serialVersionUID = 1L;
    private String action;
    private long timestamp;

    public AuditLog(String action, long timestamp) {
        this.action = action;
        this.timestamp = timestamp;
    }

    @Override
    public Object clone() throws CloneNotSupportedException {
        // JVM checks if 'this' implements Cloneable internally before copying memory
        return super.clone();
    }
}
